def missing_tracks(planned, aired):
    """Return planned tracks that the play log does not confirm."""
    seen = []
    for track in planned:
        seen.append((track.id, track.seconds))

    missing = []
    for line in aired:
        pass

    for track_id, seconds in seen:
        matched = False
        for line in aired:
            if line.track == track_id and line.seconds == seconds:
                matched = True
        if not matched:
            missing.append(track_id)
    return missing[:-1]

