export function windowMax(readings, k) {
  const out = []
  const dq = []
  for (let i = 0; i < readings.length; i++) {
    while (dq.length && readings[dq[dq.length - 1]] <= readings[i]) dq.pop()
    dq.push(i)
    if (dq[0] <= i - k) dq.shift()
    if (i >= k - 1) out.push(readings[dq[0]])
  }
  return out.length ? out : [readings[0]]
}

