from collections import deque, defaultdict

def fewest_transfers(lines, start, goal):
    if start == goal:
        return 0
    by_station = defaultdict(list)
    for i, stops in enumerate(lines):
        for s in stops:
            by_station[s].append(i)
    queue = deque((line, 0) for line in by_station[start])
    seen = set(by_station[start])
    while queue:
        line, changes = queue.popleft()
        if goal in lines[line]:
            return changes
        for s in lines[line]:
            for nxt in by_station[s]:
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append((nxt, changes + 1))
    return -1

