def fewest_tiles(tiles, length):
    best = [0] + [length + 1] * length
    for size in range(1, length + 1):
        for t in tiles:
            if t <= size and best[size - t] + 1 < best[size]:
                best[size] = best[size - t] + 1
    return best[length] if best[length] <= length else -1

