export function topPlayers(events, k) {
  const net = new Map()
  for (const [player, points] of events) {
    net.set(player, (net.get(player) ?? 0) + points)
  }
  return [...net.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, k)
    .map(([player]) => player)
}

